mapper.select:
SELECT L.LIB_ID AS libId, (L.USE_IND = 'Y') AS active
  FROM LIBMSTR L
 WHERE L.LIB_ID = #{libId}

mapper.sql:
WHERE T.LIB_ID = #{libId}
  AND ()

  AND T.DEL_IND = 'N'


  AND T.ORG_MSTR_CODE = #{f.regionCode}


  AND T.ORG_CODE = #{f.districtCode}


  AND T.STAGE_CODE = #{f.stageId}


  AND T.STATUS_CODE = #{f.status}


  AND T.PHONE_LAST4 = #{f.phoneLast4}


  AND T.FOUND_DATE >= #{f.foundFrom}


  AND T.FOUND_DATE <= #{f.foundTo}


  AND (LOCATE(#{f.q}, T.TGT_NAME_HAN) > 0 OR LOCATE(#{f.q}, IFNULL(T.TGT_CODE, '')) > 0)

mapper.select:
SELECT 
  FROM TGMSTR T
 WHERE T.LIB_ID = #{libId}
   AND T.TGT_ID = #{id}
   AND ()

mapper.update:
UPDATE TGMSTR T
T.TGT_CODE = #{code}, T.TGT_NAME_HAN = #{name}, T.SEX_CODE = #{gender}, T.AGE = #{age}, T.AGE_BASE_DATE = #{ageAsOf}, T.FOUND_DATE = #{foundDate}, T.FOUND_TIME = #{foundTime}, T.DATE_UNKNOWN_IND = IF(#{dateUnknown}, 'Y', 'N'), T.CLASS1_CODE = #{classification1}, T.CLASS2_CODE = #{classification2}, T.PLACE_NAME = #{place}, T.TOOL_NAME = #{tool}, T.RESIDENCE = #{residence}, T.TEACHER_NAME = #{teacher}, T.REASON = #{reason}, T.WORKER_NAME = #{worker}, T.EMPL_ID = #{introducerId}, T.INTRO_EMPL_CODE = #{introducerCode}, T.INTRO_NAME = #{introducerName}, T.INTRO_ORG_SNAPSHOT = #{introducerOrg}, T.ORG_MSTR_CODE = #{regionCode}, T.ORG_CODE = #{districtCode}, T.BAN_CODE = #{className}, T.JOB_CODE = #{employment}, T.STAGE_CODE = #{stageId}, T.STATUS_CODE = #{status}, T.APPOINTMENT_TEXT = #{appointment}, T.NOTES = #{notes}, T.CUSTOM_JSON = #{custom}, T.MANPIK_DATE = #{manpikDate}, T.FIND_A_DATE = #{findADate}, T.HAB_B_DATE = #{habBDate}, T.HAB_A_DATE = #{habADate}, T.YOUNG_TTA_DATE = #{youngTtaDate}, T.BOKSHIN_DATE = #{bokshinDate}, T.CARD_RECEIVED_DATE = #{cardReceivedDate}, T.CENTER_REGISTERED_DATE = #{centerRegisteredDate}, T.DEL_IND = IF(#{deleted}, 'Y', 'N'), T.PHONE_ENC = #{phoneEnc}, T.PHONE_LAST4 = #{phoneLast4}, T.PHONE_KEY_VER = #{phoneKeyVer}, T.ROW_VERSION = T.ROW_VERSION + 1, T.SYS_MUSR_ID = #{sysUserId}, T.SYS_MUSR_IP = #{sysIp}, T.SYS_MUSR_DTTM = #{sysAt}
WHERE T.TGT_ID = #{id} AND T.LIB_ID = #{libId} AND T.ROW_VERSION = #{expectedVersion} AND ()

UPDATE TGMSTR T
   SET T.PHONE_ENC = #{phoneEnc},
       T.PHONE_LAST4 = #{phoneLast4},
       T.PHONE_KEY_VER = #{phoneKeyVer}
 WHERE T.TGT_ID = #{id}
   AND T.LIB_ID = #{libId}
   AND T.PHONE_ENC IS NULL

mapper.sql:
WHERE A.LIB_ID = #{libId}
  AND A.DEL_IND = 'N'
  AND ()

  AND A.TGT_ID = #{f.personId}


  AND A.TGT_ID IS NULL


  AND A.TGT_ID IS NOT NULL


  AND A.ORG_MSTR_CODE = #{f.regionCode}


  AND A.ORG_CODE = #{f.districtCode}


  AND A.ACT_DATE >= #{f.from}


  AND A.ACT_DATE <= #{f.to}

mapper.select:
SELECT 
  FROM ACTMSTR A
 WHERE A.LIB_ID = #{libId}
   AND A.ACT_ID = #{id}
   AND ()

mapper.update:
UPDATE ACTMSTR A
A.ACT_CODE = #{code}, A.ACT_DATE = #{date}, A.START_TIME = #{startTime}, A.END_TIME = #{endTime}, A.ACT_MINUTES = #{minutes}, A.CLASS2_CODE = #{classification2}, A.SESSION_KEY = #{sessionKey}, A.EMPL_ID = #{workerId}, A.EMPL_CODE = #{workerCode}, A.EMPL_NAME = #{worker}, A.ORG_MSTR_CODE = #{regionCode}, A.ORG_CODE = #{districtCode}, A.BAN_CODE = #{className}, A.PLACE_NAME = #{place}, A.ACT_KIND_NAME = #{type}, A.MEMO = #{memo}, A.DEL_IND = IF(#{deleted}, 'Y', 'N'), A.ROW_VERSION = A.ROW_VERSION + 1, A.SYS_MUSR_ID = #{sysUserId}, A.SYS_MUSR_IP = #{sysIp}, A.SYS_MUSR_DTTM = #{sysAt}
WHERE A.ACT_ID = #{id} AND A.LIB_ID = #{libId} AND A.ROW_VERSION = #{expectedVersion} AND ()

mapper.sql:
SELECT 'STAGE' AS kind, 1 AS kindRank, L.STG_LOG_ID AS id, L.TGT_ID AS personId, T.ORG_MSTR_CODE AS regionCode, T.ORG_CODE AS districtCode, L.FROM_STAGE AS fromValue, L.TO_STAGE AS toValue, DATE_FORMAT(L.APPLY_DTTM, '%Y-%m-%dT%H:%i:%s') AS effectiveAt, DATE_FORMAT(L.RECORDED_DTTM, '%Y-%m-%dT%H:%i:%sZ') AS recordedAt, IF(L.TIME_UNKNOWN_IND = 'Y', 1, 0) AS timeUnknown, IF(L.BASELINE_IND = 'Y', 1, 0) AS baseline, L.ACTOR_ID AS actorId, L.ACTOR_NAME AS actorName, L.REASON AS reason, CAST(NULL AS CHAR) AS action, CAST(NULL AS CHAR) AS targetKind, CAST(NULL AS CHAR) AS targetId, COALESCE(L.APPLY_DTTM, L.RECORDED_DTTM) AS sortAt FROM TGSTGLOG L JOIN TGMSTR T ON T.TGT_ID = L.TGT_ID AND T.LIB_ID = L.LIB_ID WHERE L.LIB_ID = #{libId} AND ()
AND L.TGT_ID = #{f.personId}
UNION ALL SELECT 'STATUS' AS kind, 2 AS kindRank, L.STAT_LOG_ID AS id, L.TGT_ID AS personId, T.ORG_MSTR_CODE AS regionCode, T.ORG_CODE AS districtCode, L.FROM_STATUS AS fromValue, L.TO_STATUS AS toValue, DATE_FORMAT(L.APPLY_DTTM, '%Y-%m-%dT%H:%i:%s') AS effectiveAt, DATE_FORMAT(L.RECORDED_DTTM, '%Y-%m-%dT%H:%i:%sZ') AS recordedAt, 0 AS timeUnknown, 0 AS baseline, L.ACTOR_ID AS actorId, L.ACTOR_NAME AS actorName, L.REASON AS reason, CAST(NULL AS CHAR) AS action, CAST(NULL AS CHAR) AS targetKind, CAST(NULL AS CHAR) AS targetId, COALESCE(L.APPLY_DTTM, L.RECORDED_DTTM) AS sortAt FROM TGSTATLOG L JOIN TGMSTR T ON T.TGT_ID = L.TGT_ID AND T.LIB_ID = L.LIB_ID WHERE L.LIB_ID = #{libId} AND ()
AND L.TGT_ID = #{f.personId}
UNION ALL SELECT 'CHANGE' AS kind, 3 AS kindRank, C.CHG_ID AS id, COALESCE(T.TGT_ID, V.TGT_ID) AS personId, COALESCE(T.ORG_MSTR_CODE, V.ORG_MSTR_CODE, A.ORG_MSTR_CODE) AS regionCode, COALESCE(T.ORG_CODE, V.ORG_CODE, A.ORG_CODE) AS districtCode, CAST(NULL AS CHAR) AS fromValue, CAST(NULL AS CHAR) AS toValue, CAST(NULL AS CHAR) AS effectiveAt, DATE_FORMAT(C.ACT_DTTM, '%Y-%m-%dT%H:%i:%sZ') AS recordedAt, 0 AS timeUnknown, 0 AS baseline, C.ACTOR_ID AS actorId, C.ACTOR_NAME AS actorName, CAST(NULL AS CHAR) AS reason, C.ACTION_NAME AS action, C.TARGET_KIND AS targetKind, C.TARGET_ID AS targetId, C.ACT_DTTM AS sortAt FROM CHGLOG C LEFT JOIN TGMSTR T ON T.LIB_ID = C.LIB_ID AND T.TGT_ID = CASE WHEN C.TARGET_KIND = 'TGMSTR' AND C.TARGET_ID REGEXP '^[1-9][0-9]{0,18}$' THEN CAST(C.TARGET_ID AS UNSIGNED) END LEFT JOIN TGMSTR V ON V.LIB_ID = C.LIB_ID AND V.LEGACY_ID = CASE WHEN C.TARGET_KIND IS NULL THEN C.TARGET_ID END LEFT JOIN ACTMSTR A ON A.LIB_ID = C.LIB_ID AND A.ACT_ID = CASE WHEN C.TARGET_KIND = 'ACTMSTR' AND C.TARGET_ID REGEXP '^[1-9][0-9]{0,18}$' THEN CAST(C.TARGET_ID AS UNSIGNED) END WHERE C.LIB_ID = #{libId} AND C.ACTION_NAME NOT IN ('person.stage', 'person.dropout', 'person.return') AND (
1 = 1 1 = 0
(T.TGT_ID IS NOT NULL AND ()) OR (V.TGT_ID IS NOT NULL AND ()) OR (A.ACT_ID IS NOT NULL AND ()) OR (T.TGT_ID IS NULL AND V.TGT_ID IS NULL AND A.ACT_ID IS NULL)
)
AND (T.TGT_ID = #{f.personId} OR V.TGT_ID = #{f.personId})

WHERE 1 = 1

  AND u.kind = #{f.kind}


  AND u.sortAt >= #{f.from}


  AND u.sortAt < DATE_ADD(#{f.to}, INTERVAL 1 DAY)

mapper.select:
SELECT IFNULL(L.FROM_STAGE, '-') AS fromValue, IFNULL(L.TO_STAGE, '-') AS toValue, COUNT(*) AS cnt FROM TGSTGLOG L JOIN TGMSTR T ON T.TGT_ID = L.TGT_ID AND T.LIB_ID = L.LIB_ID WHERE L.LIB_ID = #{libId} AND L.BASELINE_IND = 'N' AND L.APPLY_DTTM IS NOT NULL AND ()
AND T.ORG_MSTR_CODE = #{f.regionCode}
AND T.ORG_CODE = #{f.districtCode}
AND L.APPLY_DTTM >= #{f.from}
AND L.APPLY_DTTM < DATE_ADD(#{f.to}, INTERVAL 1 DAY)
GROUP BY IFNULL(L.FROM_STAGE, '-'), IFNULL(L.TO_STAGE, '-') ORDER BY cnt DESC, fromValue, toValue

mapper.insert:
INSERT INTO TGSTATLOG
       (LIB_ID, TGT_ID, SEQ_NO, FROM_STATUS, TO_STATUS, APPLY_DTTM, RECORDED_DTTM, ACTOR_ID, ACTOR_NAME, REASON,
        ORG_MSTR_CODE, ORG_CODE, BAN_CODE,
        SYS_RUSR_ID, SYS_RUSR_IP, SYS_RUSR_DTTM, SYS_MUSR_ID, SYS_MUSR_IP, SYS_MUSR_DTTM)
SELECT #{libId}, T.TGT_ID, #{seq}, #{fromValue}, #{toValue}, #{effectiveAt}, #{recordedAt}, #{actorId}, #{actorName}, #{reason},
       T.ORG_MSTR_CODE, T.ORG_CODE, T.BAN_CODE,
       #{sysUserId}, #{sysIp}, #{sysAt}, #{sysUserId}, #{sysIp}, #{sysAt}
  FROM TGMSTR T
 WHERE T.TGT_ID = #{personId}
   AND T.LIB_ID = #{libId}
